def pick(xs: list[int], seed: int) -> int:
    """Return an element of the non-empty list xs, chosen deterministically from seed.

    The same (xs, seed) pair always yields the same element. No randomness is used.
    """
    return xs[seed % len(xs)]


def test_pick_returns_member() -> None:
    xs = [10, 20, 30, 40]
    for seed in range(50):
        assert pick(xs, seed) in xs


def test_pick_same_seed_same_element() -> None:
    xs = [5, 6, 7, 8, 9]
    for seed in range(20):
        assert pick(xs, seed) == pick(xs, seed)


def test_pick_single_element() -> None:
    for seed in (-3, 0, 1, 99999):
        assert pick([42], seed) == 42


def test_pick_varies_with_seed() -> None:
    xs = [1, 2, 3, 4]
    seen = {pick(xs, seed) for seed in range(100)}
    assert len(seen) > 1


def test_pick_negative_seed() -> None:
    xs = [1, 2, 3]
    first = pick(xs, -7)
    assert first in xs
    assert pick(xs, -7) == first


def test_pick_does_not_mutate() -> None:
    xs = [3, 1, 2]
    pick(xs, 4)
    assert xs == [3, 1, 2]
